-- GENERATED by `python3 analytics/build.py render` from analytics/dbt/models/marts/int_patient_key.sql, analytics/dbt/models/marts/int_patient_demographics.sql. Do not edit.
-- Internal: one row per patient record with its salted keys. patient_record_sk stands for the record, patient_sk for
-- the person (the master id of gold_patient_crosswalk, so records the EMPI linked share it). Every mart takes its
-- patient keys from here. Holds the FHIR patient id, so it is for building the marts only, never for BI users.
CREATE OR REPLACE TABLE int_patient_key AS
SELECT
    x.patient_id,
    x.source,
    x.master_id,
    MD5((SELECT pseudonym_salt FROM governance_settings) || '|' || COALESCE(CAST(x.patient_id AS VARCHAR), ''))     AS patient_record_sk,
    MD5((SELECT pseudonym_salt FROM governance_settings) || '|' || COALESCE(CAST(x.master_id AS VARCHAR), ''))      AS patient_sk
FROM gold_patient_crosswalk x;

-- Internal: the demographics the snapshot snap_patient_demographics tracks (SCD type 2), one row per patient record,
-- as of the extract (loaded_at). Address, sex and the deceased flag; the address is identifying, so this model and the
-- snapshot are for building the marts only. dim_patient_history shows the history without the address itself.
CREATE OR REPLACE TABLE int_patient_demographics AS
WITH latest AS (
    SELECT *
    FROM bronze_resources
    WHERE resource_type = 'Patient'
    QUALIFY ROW_NUMBER() OVER (PARTITION BY resource_id ORDER BY loaded_at DESC, bronze_id DESC) = 1
)
SELECT
    p.patient_id,
    p.source,
    l.raw:address[0].line[0]::string          AS address_line,
    p.city,
    p.state,
    p.postal_code,
    p.gender                                               AS sex,
    p.is_deceased,
    p.loaded_at
FROM silver_patient p
JOIN latest l ON l.resource_id = p.patient_id;
